export const mat1Tasks={"charge": [{"id": "compare", "title": "Compare and explain", "kind": "charge", "type": "compare", "cases": [["0", "Rubbing certain insulators transfers…", ["Electrons", "Protons between nuclei", "Newly created charge"], 0, "Electrons can move between surfaces."], ["1", "An object gaining electrons becomes…", ["Positive", "Negative", "Necessarily neutral"], 1, "Electrons carry negative charge."], ["2", "An object losing electrons becomes…", ["Negative", "A new chemical element", "Positive"], 2, "Its positive charge is no longer balanced."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "charge-data", "type": "numeric", "prompt": "A fresh neutral model begins with12 electrons. It loses5. How many remain?", "answer": 7, "unit": "electrons", "reasonChoices": ["12 − 5", "12 + 5", "12 × 5"], "reason": 0, "why": "Use the stated account or relationship; check the units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "charge-model", "type": "experiment", "experiment": "charge", "why": "Check source signs, process boundaries or measured quantities."}], "forces": [{"id": "compare", "title": "Compare and explain", "kind": "forces", "type": "compare", "cases": [["0", "Two positive charges…", ["Repel", "Attract", "Exert force only when touching"], 0, "Like signs repel."], ["1", "A positive and a negative charge…", ["Repel", "Attract", "Cancel every force at a distance"], 1, "Unlike signs attract."], ["2", "Two negative charges…", ["Attract", "Cannot exert any force", "Repel"], 2, "Like signs repel regardless of sign."]]}, {"id": "evidence", "title": "Interpret the evidence", "kind": "forces", "type": "compare", "cases": [["0", "An unknown object is attracted to a charged rod. What does attraction alone establish?", ["Attraction alone cannot determine the unknown net sign", "Yes, attraction proves negative charge", "No, attraction always proves positive charge"], 0, "Interpret only what the evidence establishes."], ["1", "Which pair definitely repels in this charged-pair model?", ["One positive and one negative", "Two negative objects", "A charged object and an unspecified neutral object"], 1, "Like signs repel."], ["2", "What is directly observed in this model?", ["An exact force in newtons", "A measured real acceleration", "Direction of the force response"], 2, "The arrows and displacement are qualitative."]]}, {"id": "model", "title": "Predict and compare every setting", "kind": "forces-model", "type": "experiment", "experiment": "forces", "why": "Check source signs, process boundaries or measured quantities."}], "fields": [{"id": "compare", "title": "Compare and explain", "kind": "fields", "type": "compare", "cases": [["0", "The field around an isolated positive sphere points…", ["Radially outward", "Radially inward", "In circles with no radial direction"], 0, "Use force direction on a positive test charge."], ["1", "Around an isolated negative sphere it points…", ["Radially outward", "Radially inward", "Only upwards"], 1, "Field direction uses a positive test charge."], ["2", "For the same source/test charges, force is stronger…", ["Farther away in every case", "Only when they touch", "Closer to the source"], 2, "The field is stronger close to the charge."]]}, {"id": "sequence", "title": "Build the process in order", "kind": "fields-sequence", "type": "sequence", "why": "Order the causal steps, not just the labels.", "route": ["build", "conduct", "flow", "reduce"], "labels": ["Charge builds and strengthens the field", "Air gap becomes conducting", "Charge flows across the gap", "Charge imbalance and field decrease"]}, {"id": "model", "title": "Predict and compare every setting", "kind": "fields-model", "type": "experiment", "experiment": "fields", "why": "Check source signs, process boundaries or measured quantities."}], "density": [{"id": "compare", "title": "Compare and explain", "kind": "density", "type": "compare", "cases": [["0", "Density is…", ["Mass ÷ volume", "Volume ÷ mass", "Mass × volume"], 0, "ρ = m/V."], ["1", "SI density units are…", ["kg × m³", "kg/m³", "m³/kg"], 1, "Use kilograms divided by cubic metres."], ["2", "An irregular solid displaces volume equal to…", ["The final reading alone", "The initial reading alone", "The increase in cylinder reading"], 2, "Subtract before from after."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "density-data", "type": "numeric", "prompt": "A fresh regular block measures2 cm ×3 cm ×4 cm and has mass72 g. Calculate density.", "answer": 3, "unit": "g/cm³", "reasonChoices": ["72 ÷ (2 × 3 × 4)", "72 × (2 × 3 × 4)", "(2 × 3 × 4) ÷ 72"], "reason": 0, "why": "Use the stated account or relationship; check the units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "density-model", "type": "experiment", "experiment": "density", "why": "Check source signs, process boundaries or measured quantities."}], "states": [{"id": "compare", "title": "Compare and explain", "kind": "states", "type": "compare", "cases": [["0", "Melting changes…", ["Solid to liquid", "Liquid to solid", "Gas to liquid"], 0, "Name the starting and finishing states."], ["1", "Condensation changes…", ["Liquid to gas", "Gas to liquid", "Solid directly to gas"], 1, "Gas becomes liquid."], ["2", "During a state change in a sealed sample, mass…", ["Is created when gas forms", "Must fall to zero", "Is conserved"], 2, "No particles leave or are destroyed."]]}, {"id": "sequence", "title": "Build the process in order", "kind": "states-sequence", "type": "sequence", "why": "Order the causal steps, not just the labels.", "route": ["solid", "liquid", "gas", "liquid2", "solid2"], "labels": ["Solid sample", "Melt to liquid", "Vaporise to gas", "Condense to liquid", "Freeze back to solid"]}, {"id": "model", "title": "Predict and compare every setting", "kind": "states-model", "type": "experiment", "experiment": "states", "why": "Check source signs, process boundaries or measured quantities."}]};
export const experimentOptions={"charge": {"a": [["A", "Surface A gains"], ["B", "Surface B gains"]], "b": [["2", "2 electrons"], ["4", "4 electrons"]], "labels": ["Gaining surface (starts with8 electrons)", "Transferred count"], "unit": "electrons on gaining surface"}, "forces": {"a": [["positive", "Positive"], ["negative", "Negative"]], "b": [["positive", "Positive"], ["negative", "Negative"]], "labels": ["Left charge", "Right charge"], "unit": "predicted interaction", "choices": [["repel", "Repel"], ["attract", "Attract"]]}, "fields": {"a": [["positive", "Positive sphere"], ["negative", "Negative sphere"]], "b": [["near", "Near source"], ["far", "Farther away"]], "labels": ["Source sign", "Observation point"], "unit": "direction and relative strength", "choices": [["out-strong", "Outward / stronger"], ["out-weak", "Outward / weaker"], ["in-strong", "Inward / stronger"], ["in-weak", "Inward / weaker"]]}, "density": {"a": [["regular", "Regular cuboid"], ["irregular", "Irregular solid"], ["liquid", "Liquid"]], "b": [["A", "Sample A"], ["B", "Sample B"]], "labels": ["Measurement method", "Original illustrative sample"], "unit": "g/cm³ density"}, "states": {"a": [["melt", "Melting"], ["freeze", "Freezing"], ["vaporise", "Vaporisation (boil/evaporate)"], ["condense", "Condensation"], ["sublime", "Sublimation"]], "b": [["20", "20 g sealed sample"], ["40", "40 g sealed sample"]], "labels": ["Process", "Conserved sample mass"], "unit": "final state / sealed mass", "choices": [["solid-same", "Solid / mass unchanged"], ["liquid-same", "Liquid / mass unchanged"], ["gas-same", "Gas / mass unchanged"], ["gas-lost", "Gas / mass destroyed"]]}};
export const tasksForMat1=k=>mat1Tasks[k];export const validMat1=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericMat1=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceMat1=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;
export const densityData={regular:{A:{mass:60,dimensions:[2,2,5]},B:{mass:120,dimensions:[2,3,5]}},irregular:{A:{mass:60,before:30,after:50},B:{mass:150,before:35,after:65}},liquid:{A:{empty:40,filled:80,volume:50},B:{empty:40,filled:100,volume:50}}};
export function densityReading(method,sample){let d=densityData[method]?.[sample];if(!d)throw new RangeError('Choose stated method and sample.');let volume=method==='regular'?d.dimensions.reduce((a,b)=>a*b):method==='irregular'?d.after-d.before:d.volume,mass=method==='liquid'?d.filled-d.empty:d.mass;return{...d,mass,volume,value:mass/volume};}
export const finalStates={melt:'liquid',freeze:'solid',vaporise:'gas',condense:'liquid',sublime:'gas'};
export function experimentResult(k,a,b){let o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated settings.');let value=k==='charge'?8+Number(b):k==='forces'?(a===b?'repel':'attract'):k==='fields'?(a==='positive'?'out':'in')+'-'+(b==='near'?'strong':'weak'):k==='states'?finalStates[a]+'-same':densityReading(a,b).value;return{value,a,b,...(k==='density'?densityReading(a,b):{})};}
export const predictionValid=(k,v,r)=>experimentOptions[k].choices?v===r.value:numericMat1(v,r.value);
export const outputLabel=(k,v)=>experimentOptions[k].choices?.find(x=>x[0]===v)?.[1]??Number(Number(v).toFixed(3))+' '+experimentOptions[k].unit;
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
